// ==== 变量定义 ====
var hosts = [
  "https://modtianmingyun-fanqie1.ms.show",
  "https://modtianmingyun-fanqie2.ms.show",
  "https://modtianmingyun-fanqie3.ms.show",
  "https://modtianmingyun-fanqie4.ms.show",
  "https://modtianmingyun-fanqie5.ms.show",
  "https://modtianmingyun-fanqie6.ms.show"
];

const version = '2.10.13';
const project = '书源：Syiism.  接口：system'
var sytjs = getSytjs();

function login() {}

// ===== 工具函数 =====
// 登录及登录检查
function login_(openBrowser, checkMode) {
    // java.removeCookie("snssdk.com")
    var cookie_ = String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token']
    // java.toast(cookie_)
    if (cookie_ && cookie_ != "" && !checkMode) {
        if (!source.variableComment) {
            java.toast("请不要重复登录，请先退出登录！")
        } else {
            java.toast("您为填写token登录，请手动移除token后再次登录")
        }
        return false
    }
    if (openBrowser) {
        try {
            java.startBrowserAwait("https://fanqienovel.com/", "登录")
        } catch (e) {
            java.toast(e)
        }
    }
    // java.log("snssdk cookie: " + java.getCookie("snssdk.com") + "will be reomved")
    try {
        cookie.removeCookie("snssdk.com")
    } catch (e) {}
    // java.log(cookie)
    var cookie_ = "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token'])
    let user
    try {
      user = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
        method: "GET",
        headers: {
          "Cookie": cookie_
        }
      }))).data.name
     } catch (e) {java.log(e)}
    if (!cookie_ || cookie_ == "sessionid=" || !user) {
        java.toast("未获取到登录凭据，登录失败")
        return false
    }
    java.toast("欢迎 " + user + "\n登录成功！" + java.getThemeConfig())
    return true
}

// 取消登录
function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    if (source.getLoginInfoMap()['手动登录Token']) java.toast("请手动移除填写的Token")
    else java.toast("退出登录成功");
}
function logToken() {
  java.log(
    String(
      cookie.getKey(
        "fanqienovel.com",
        "sessionid"
      )
    ) ? String(
     cookie.getKey(
        "fanqienovel.com", 
        "sessionid"
      )
    ) : (
     source.getLoginInfoMap()
      ? source.getLoginInfoMap()
      : {}
    )['手动登录Token']
  )
  java.toast("登录Token已打印到日志，请妥善保管")
}

function began() {
  source.setVariable(JSON.stringify({
  	'sytjs': sytjs,
  	'sytj_type': '',
  	'sytj_title': '',
  	"频道": "男频",
  "bd_id": 2,
  "tone": "tone_id=0",
  "server_id": 0,
  "server": hosts[0],
  "hosts": hosts,
  "type": "小说模式",
  "module": 3,
  "showPara": false,
  "showChap": false,
  "showBook": true,
  "isPlayer": false,
  "tone_cn": "",
  }, null, '\t'));
  java.toast("已初始化源变量！");
}

function clean() {
    source.setVariable('');
    java.toast("源变量已清除");
 }

function toggleParaComments() {
	   let t = GET('showPara');
    SET('showPara', !t);
    java.toast(!t ? "\n💬打开段评💬" : "\n🚫关闭段评🚫");
}

function toggleChapComments() {
	   let t = GET('showChap');
    SET('showChap', !t);
    java.toast(!t ? "\n💬打开章评💬" : "\n🚫关闭章评🚫");
}

function checkPlayer() {
  	   let t = GET('isPlayer');
    SET('isPlayer', !t);
    java.toast(!t ? "\n▶️启用阅读播放器▶️" : "\n⏸️启用第三方播放器⏸️");
}

// 设置类型
function setType(Type) {
    SET('type', Type);
    if (Type == '朗读模式') {
        SET('module', "2");
    } else if (Type == '小说模式') {
        SET('module', "3");
        SET('bd_id', '2');      
        SET('tone', '');
        SET('tone_cn', '');
    } else if (Type == '听书模式') {
        SET('module', "2");
        SET('bd_id', '6'); 
    } else if (Type == '漫画模式') {
        SET('module', "8");
        SET('tone', '');
        SET('tone_cn', '');
    } else if (Type == '短剧模式') {
        SET('module', "11");
        SET('bd_id', '4'); 
        SET('tone', '');
        SET('tone_cn', '');
    } else if (Type == '短篇模式') {
        SET('module', "13");
        SET('bd_id', '7'); 
        SET('tone', '');
        SET('tone_cn', '');
    } else if (Type == '漫剧模式') {
        SET('module', "19");
        SET('bd_id', '5');
        SET('tone', '');
        SET('tone_cn', '');
    }
    java.toast('已将类型切换为:\n' + Type + '\n需要刷新发现页');
}

// 设置音色
function setVoice(num) {
    var data = _getTones();

    if (num < 0 || num >= data.length) { java.longToast("无效的接口编号！"); return; }
    SET('tone', data[num][1]);
    SET('tone_cn', data[num][0]+`(${GET('tone')})`);
    java.longToast("设置成功\n当前模式：" + (GET('type') || "未知模式") + "\n音色设置：" + data[num][0] + '[' + data[num][1] + ']' + "\n‼️设置完成请点击切换模式‼️");
}

// 
function currenMode() {
    java.longToast("\n当前模式：" + (GET('type') || "未知模式") + "\n音色设置：" + GET('tone_cn') + "\n段评：" + (GET("showPara") ? "💬打开💬" : "🚫关闭🚫") + "\n章评：" + (GET("showChap") ? "💬打开💬" : "🚫关闭🚫"));
}

// 检测服务器
function checkNet() {
    let url = GET('server');
    java.longToast(`\n\n♻️正在检测：${url}\n请稍等~`);
    let date1 = new Date().getTime();
    let html = java.log(java.ajax(url));
    let date2 = new Date().getTime();
    let t = date2 - date1;
    let time = t / 1000 + 's';
    let logTime = '【' + url + '】\n┋┋\n' + '解析时间：' + time;

    if (t > 5000) {
        java.longToast('\n' + 
                      '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + 
                      logTime + '\n┋┋\n♣️当前接口♣️\n┋┋\n请切换其他接口/切换网络环境\n┋┋' + 
                      '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t < 1000) {
        java.longToast('\n💖【网络环境优良】\n' + 
                      '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + 
                      logTime + '\n┋┋\n❤️延迟低，推荐使用此接口❤️\n┋┋\n网络环境优良，请继续保持状态\n┋┋' + 
                      '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t >= 1000 && t < 2000) {
        java.longToast('\n💛【网络环境一般】\n' + 
                      '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + 
                      logTime + '\n┋┋\n♦️延迟一般，勉强可使用♦️\n┋┋\n请切换其他接口或切换网络环境\n┋┋' + 
                      '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t >= 2000 && t < 5000) {
        java.longToast('\n💔【网络环境堪忧】\n' + 
                      '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + 
                      logTime + '\n┋┋\n♠延迟过高，不建议使用♠\n┋┋\n请切换其他接口或切换网络环境\n┋┋' + 
                      '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    }
